// ===== CONFIGURA AQUÍ =====
// 1) Link de tu Google Sheet (la hoja Bombi_Control_Ventas importada)
const SHEET_URL = 'https://docs.google.com/spreadsheets/d/TU_SHEET_ID/edit?gid=1554250418#gid=1554250418';
// Modelo de Gemini (gratis en AI Studio). Si algún día falla, cámbialo por otro Flash de ai.google.dev/gemini-api/docs/models
const MODELO = 'gemini-3.1-flash-lite';
// 2) IDs de Telegram que pueden usar el bot (tú y tu novia).
//    Déjalo vacío al principio; escríbele al bot y te dirá tu ID. Luego agrégalos así: [123456789, 987654321]
const PERMITIDOS = [/* IDs de Telegram omitidos en el repo */];
// ==========================

const salida = [];
for (const item of $input.all()) {
  const u = item.json.message?.from || item.json.callback_query?.from;
  if (PERMITIDOS.length && !PERMITIDOS.includes(u?.id)) continue; // ignora a desconocidos
  item.json.cfg = { sheetUrl: SHEET_URL, modelo: MODELO };
  salida.push(item);
}
return salida;

const msg = $('Telegram Trigger').first().json.message;
const hoy = DateTime.now().setZone('America/Caracas').toFormat('yyyy-MM-dd');
const img = $input.first().json.img;            // solo existe si mandaron foto
const texto = msg.text || msg.caption || '';

const sistema = `Eres el asistente de registro de Bombi, un emprendimiento de galletas y brownies en Venezuela.
Recibes una captura de pago o un mensaje escrito, y devuelves SOLO un objeto JSON, sin texto adicional.

Decide el tipo:
- "venta": un cliente pagó a Bombi (capturas de pago móvil, transferencias, Zelle, Binance, o mensajes como "vendí 6 NY cookies en 15$").
- "gasto": Bombi compró algo (mensajes como "gasto harina 5$", "compré empaques 300 bs").
- "desconocido": si no es ninguno de los dos o falta el monto.

Formato exacto:
{"tipo":"venta|gasto|desconocido","fecha":"YYYY-MM-DD","monto":0,"moneda":"Bs|USD","metodo":"","banco":"","referencia":"","producto":"","cantidad":null,"cliente":"","concepto":"","categoria":"","proveedor":""}

Reglas:
- Hoy es ${hoy}. Usa la fecha de la captura si se ve; si no, usa hoy.
- monto es un número sin separadores de miles: "1.234,56 Bs" -> 1234.56.
- moneda: "Bs" para bolívares (pago móvil, transferencia y punto de venta casi siempre son Bs); "USD" si dice $, dólares, Zelle o USDT.
- metodo debe ser uno de: Pago Móvil, Transferencia, Efectivo Bs, Efectivo USD, Zelle, Binance, Punto de venta. Si dicen "efectivo" con $, es Efectivo USD.
- referencia: el número de referencia/operación tal como aparece (solo dígitos y letras), o "".
- banco: banco emisor del pago si se ve (Banesco, Mercantil, Venezuela, Provincial, BNC, etc.), o "".
- cliente: nombre o teléfono del pagador si aparece, o "".
- producto y cantidad: solo si el texto lo dice (ej. "6 NY cookies" -> producto "NY Cookies", cantidad 6).
- Para gastos: concepto (qué se compró), categoria (Ingredientes, Empaques, Delivery, Servicios, Equipos, Publicidad u Otros) y proveedor si lo dicen.
- Deja "" en los campos que no apliquen. No inventes datos.`;

const parts = [];
if (img) parts.push({ inline_data: { mime_type: 'image/jpeg', data: img } });
parts.push({ text: img ? `Captura de pago. Texto que la acompaña: ${texto || '(ninguno)'}` : `Mensaje: ${texto}` });

return [{ json: {
  modelo: $('Config').first().json.cfg.modelo,
  body: {
    system_instruction: { parts: [{ text: sistema }] },
    contents: [{ role: 'user', parts }],
    generationConfig: { temperature: 0, responseMimeType: 'application/json' }
  }
} }];

const caption = $('Telegram Trigger').first().json.message?.caption || '';
const mOrden = caption.match(/orden\s*#?\s*(\d+)/i);
const ordenPago = mOrden ? Number(mOrden[1]) : '';
const from = $('Telegram Trigger').first().json.message.from;
const chatId = $('Telegram Trigger').first().json.message.chat.id;
let raw = ($('Gemini lee el pago').first().json.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
let d = {};
try { d = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) { d = { tipo: 'desconocido' }; }

const tasa = Number($input.first().json.promedio) || 0;
const now = DateTime.now().setZone('America/Caracas');
const monto = Number(d.monto) || 0;
const tipo = d.tipo === 'venta' || d.tipo === 'gasto' ? d.tipo : 'desconocido';
const ok = tipo !== 'desconocido' && monto > 0 && tasa > 0;

const moneda = d.moneda === 'USD' ? 'USD' : 'Bs';
const usd = moneda === 'USD' ? monto : Math.round((monto / tasa) * 100) / 100;
const bs = moneda === 'Bs' ? monto : Math.round(monto * tasa * 100) / 100;
const fecha = /^\d{4}-\d{2}-\d{2}$/.test(d.fecha || '') ? d.fecha : now.toFormat('yyyy-MM-dd');
const ref = String(d.referencia || '').replace(/[^0-9A-Za-z]/g, '');
const id = (tipo === 'gasto' ? 'G-' : 'V-') + now.toFormat('yyMMdd-HHmmss');
const quien = from.first_name || '';
const metodos = ['Pago Móvil','Transferencia','Efectivo Bs','Efectivo USD','Zelle','Binance','Punto de venta'];
const metodo = metodos.includes(d.metodo) ? d.metodo : (moneda === 'Bs' ? 'Pago Móvil' : 'Efectivo USD');
const txt = v => (v === null || v === undefined) ? '' : String(v);
const texto = ref ? "'" + ref : '';   // el apóstrofo evita que la hoja borre ceros a la izquierda

let registro;
if (tipo === 'gasto') {
  registro = { 'ID': id, 'Fecha': fecha, 'Hora': now.toFormat('HH:mm'), 'Concepto': txt(d.concepto),
    'Categoría': txt(d.categoria) || 'Otros', 'Monto': monto, 'Moneda': moneda, 'Tasa BCV': tasa,
    'Monto USD': usd, 'Monto Bs': bs, 'Método': metodo, 'Proveedor': txt(d.proveedor),
    'Referencia': texto, 'Registrado por': quien };
} else {
  registro = { 'ID': id, 'Fecha': fecha, 'Hora': now.toFormat('HH:mm'), 'Producto': txt(d.producto),
    'Cantidad': d.cantidad ?? '', 'Monto': monto, 'Moneda': moneda, 'Tasa BCV': tasa,
    'Monto USD': usd, 'Monto Bs': bs, 'Método': metodo, 'Banco': txt(d.banco),
    'Referencia': texto, 'Cliente': txt(d.cliente), 'Registrado por': quien };
}

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmtBs = n => n.toLocaleString('es-VE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const [y, m, dd] = fecha.split('-');
const lineas = [
  tipo === 'gasto' ? '🧾 <b>Gasto</b>' : '🍪 <b>Venta</b>',
  tipo === 'gasto' ? `Concepto: ${esc(registro['Concepto'] || '—')} (${esc(registro['Categoría'])})`
                   : `Producto: ${esc(registro['Producto'] || '—')}${registro['Cantidad'] !== '' ? ' × ' + registro['Cantidad'] : ''}`,
  `Monto: ${moneda === 'Bs' ? fmtBs(monto) + ' Bs  (≈ $' + usd.toFixed(2) + ')' : '$' + monto.toFixed(2) + '  (≈ ' + fmtBs(bs) + ' Bs)'}`,
  `Método: ${esc(metodo)}${registro['Banco'] ? ' · ' + esc(registro['Banco']) : ''}`,
  ref ? `Ref: ${esc(ref)}` : null,
  registro['Cliente'] ? `Cliente: ${esc(registro['Cliente'])}` : null,
  `Fecha: ${dd}/${m}/${y} · Tasa BCV ${fmtBs(tasa)}`,
].filter(Boolean);
registro['Orden'] = ordenPago;
return [{ json: { ok, tipo, id, chatId, ref, Orden: ordenPago, registro, resumen: lineas.join('\n'), userId: from.id,
  motivo: !tasa ? 'No pude obtener la tasa BCV ahora mismo.' : '' } }];

const r = $('Armar registro').first().json;
const dup = r.tipo === 'venta' && r.ref &&
  $input.all().some(i => String(i.json['Referencia'] ?? '').replace(/^'/, '') === r.ref);
const aviso = dup ? '\n\n⚠️ <b>Ya hay una venta con esa referencia.</b> Revisa que no sea la misma captura.' : '';
return [{ json: { ...r, texto: r.resumen + aviso + '\n\n¿Lo guardo?' } }];

const cq = $('Telegram Trigger').first().json.callback_query;
const [accion, id] = (cq.data || '').split('|');
const fila = $input.all().map(i => i.json).find(r => r['ID'] === id);
let registro = null;
try { registro = JSON.parse(fila?.['Datos'] || 'null'); } catch (e) {}
return [{ json: {
  accion, id, registro,
  tipo: fila?.['Tipo'],
  valido: !!fila && fila['Estado'] === 'pendiente' && !!registro,
  cbId: cq.id, chatId: cq.message.chat.id, msgId: cq.message.message_id,
  textoOriginal: cq.message.text || ''
} }];

