const chatId = $('Telegram Trigger').first().json.message.chat.id;
const filas = $input.all().map(i => i.json).filter(r => r['Periodo']);
const emoji = { 'Hoy': '📅', 'Esta semana': '🗓️', 'Este mes': '📆' };
const partes = filas.map(r =>
  `${emoji[r['Periodo']] || '•'} <b>${r['Periodo']}</b>\n` +
  `Ventas: ${r['Ventas USD']} (${r['Nº ventas']})\n` +
  `Gastos: ${r['Gastos USD']}\n` +
  `Ganancia: <b>${r['Ganancia USD']}</b>`);
const texto = partes.length ? '🍪 <b>Resumen Bombi</b> (USD, tasa BCV)\n\n' + partes.join('\n\n')
                            : 'No pude leer la hoja Bot. Revisa el link en el nodo Config.';
return [{ json: { chatId, texto } }];

const texto = $('Telegram Trigger').first().json.message.text;
const hoy = $now.setZone('America/Caracas').toFormat('yyyy-MM-dd (cccc)');
const prompt = `Extrae los datos de esta orden de galletas. Hoy es ${hoy}.
Si dice "viernes", usa la fecha del próximo viernes.
Responde SOLO con JSON: {"cliente":"","productos":"","monto":0,"moneda":"Bs","fecha_esperada_pago":"YYYY-MM-DD"}
Orden: ${texto}`;

return [{ json: {
  modelo: 'gemini-3.1-flash-lite',
  body: {
    contents: [{ parts: [{ text: prompt }] }],
    generationConfig: { responseMimeType: 'application/json' }
  }
}}];

// Número siguiente
const filas = $('Leer Por Cobrar').all();
const nums = filas.map(f => Number(f.json.Orden)).filter(n => n > 0);
const siguiente = nums.length ? Math.max(...nums) + 1 : 1;

// Respuesta de Gemini (vía HTTP)
let txt = $('Gemini lee la orden').first().json.candidates[0].content.parts[0].text;
const d = JSON.parse(txt.replace(/```json|```/g, '').trim());

return [{ json: {
  'Orden': siguiente,
  'Fecha entrega': $now.setZone('America/Caracas').toFormat('yyyy-MM-dd'),
  'Cliente': d.cliente,
  'Productos': d.productos,
  'Monto': Number(d.monto),
  'Moneda': d.moneda,
  'Fecha esperada pago': d.fecha_esperada_pago,
  'Estado': 'pendiente',
  'Fecha pago': '',
  'Referencia': ''
}}];
